import {
  BriefcaseBusiness,
  HomeIcon,
  Sun,
  Moon,
  DownloadCloud
} from "lucide-react";
import { useEffect, useState } from "react";
import { Link, useLocation } from "react-router-dom";

export default function Header() {
  const [darkMode, setDarkMode] = useState(false);
    const location = useLocation();

  useEffect(() => {
    const savedTheme = localStorage.getItem("theme");

    if (savedTheme === "dark") {
      setDarkMode(true);
      document.documentElement.classList.add("dark");
    }
  }, []);
  const isHomeActive = location.pathname === "/";
  const isWorkActive = location.pathname === "/work";
  const toggleTheme = () => {
    const nextTheme = !darkMode;

    setDarkMode(nextTheme);

    if (nextTheme) {
      document.documentElement.classList.add("dark");
      localStorage.setItem("theme", "dark");
    } else {
      document.documentElement.classList.remove("dark");
      localStorage.setItem("theme", "light");
    }
  };

  return (
    <header className="w-full dark:bg-[#111111] dark:text-neutral-100 ">
      <nav className="flex items-center  mx-auto w-[820px] dark:bg-[#111111] dark:text-neutral-100  justify-between px-6 py-6 sm:px-8">
        {/* Navigation */}
        <div className="flex items-center gap-8">
          {/* Home */}
            <Link
            to="/"
            className={`flex items-center gap-2 text-[16px] transition-colors ${
              isHomeActive
                ? "font-medium text-neutral-950 dark:text-white"
                : "text-neutral-400 hover:text-neutral-950 dark:text-neutral-500 dark:hover:text-white"
            }`}
          >
            <HomeIcon
              className="h-4 w-4"
              strokeWidth={1.7}
            />

            <span>Home</span>
          </Link>

          {/* Work */}
            <Link
            to="/work"
            className={`flex items-center gap-2 text-[16px] transition-colors ${
              isWorkActive
                ? "font-medium text-neutral-950 dark:text-white"
                : "text-neutral-400 hover:text-neutral-950 dark:text-neutral-500 dark:hover:text-white"
            }`}
          >
            <BriefcaseBusiness
              className="h-4 w-4"
              strokeWidth={1.7}
            />

            <span>Work</span>
          </Link>
        </div>

        <div className="flex items-center gap-3">
          <a
            href="https://drive.google.com/file/d/1pI_WUJKX30BcneKcCGq9eTQ0QN1sdKlj/view?usp=sharing"
            className="flex"
            target="_blank"
            rel="noopener noreferrer"
              aria-label="Download resume"
            >
            <span>
              <DownloadCloud
                size={1}
                className="flex h-9 w-9 p-2 items-center justify-center rounded-full text-neutral-500 transition-colors hover:bg-black/5 hover:text-neutral-950 dark:text-neutral-400 dark:hover:bg-white/10 dark:hover:text-white"
              />{" "}
            </span>
          </a>
          {/* Theme Toggle */}
          <button
            type="button"
            onClick={toggleTheme}
            aria-label={
              darkMode ? "Switch to light mode" : "Switch to dark mode"
            }
            className="flex h-9 w-9 items-center justify-center rounded-full text-neutral-500 transition-colors hover:bg-black/5 hover:text-neutral-950 dark:text-neutral-400 dark:hover:bg-white/10 dark:hover:text-white">
            {darkMode ? (
              <Sun
                className="h-[18px] w-[18px] text-orange-300"
                strokeWidth={1.7}
              />
            ) : (
              <Moon className="h-[18px] w-[18px]" strokeWidth={1.7} />
            )}
          </button>
        </div>
      </nav>
    </header>
  );
}
